          {
            "desc": "Enumerate production provider spawn call sites and prove each is either routed through the shared admission boundary or explicitly classified legacy_unmanaged with no gate claim; a new direct spawn path must make the contract test fail.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/provider-process-registry-smoke.js",
              "selector": "provider-process-registry-smoke PASS"
